function setField(){
    var missedField = false;
    for (var i = 0; i < document.getElementById('controls').getElementsByTagName('input').length; i++) {
      document.getElementById('controls').getElementsByTagName('input')[i].classList.remove('false');
      if (document.getElementById('controls').getElementsByTagName('input')[i].value == "") {
        document.getElementById('controls').getElementsByTagName('input')[i].classList.add('false');
        missedField = true;
      }
    }
    if (missedField == true) {
      alert('Кажется, вы забыли что-то важное...')
    } else {
      document.getElementsByClassName('beginning')[0].classList.add('true');
      questionNumber=document.getElementById('questionNumber').value;
      answersNumber=document.getElementById('answersNumber').value;
      for (var i = 0; i < questionNumber; i++) {
        newQuestion(i, answersNumber);
      }
      var createTest = document.createElement('button');
      createTest.innerHTML = 'Добавить результаты теста';
      createTest.setAttribute('onclick', 'createTest()');
      document.getElementById('testHolder').appendChild(createTest);
    }
  }

